import{_ as a,a as o,c as n,ac as t}from"./chunks/framework.BSuaGltH.js";const f=JSON.parse('{"title":"第一册：英语初阶 · 全册易错点 · 第1–26课","description":"逐课检查常见错误、适用边界和正确表达。","frontmatter":{"title":"第一册：英语初阶 · 全册易错点 · 第1–26课","description":"逐课检查常见错误、适用边界和正确表达。","splitFrom":"life/english/new-concept/book-1/mistakes.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"句法与表达查阅","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第一册：英语初阶 · 全册易错点","summary":"逐课检查常见错误、适用边界和正确表达。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第一册：英语初阶 · 全册易错点","link":"/life/english/new-concept/book-1/mistakes"},"next":{"text":"第一册：英语初阶 · 全册易错点 · 第27–53课","link":"/life/english/new-concept/book-1/mistakes-part-02"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第一册：英语初阶 · 全册易错点","link":"/life/english/new-concept/book-1/mistakes"},"next":{"text":"第一册：英语初阶 · 全册易错点 · 第27–53课","link":"/life/english/new-concept/book-1/mistakes-part-02"}},"headers":[],"relativePath":"life/english/new-concept/book-1/mistakes-part-01.md","filePath":"life/english/new-concept/book-1/mistakes-part-01.md"}'),s={name:"life/english/new-concept/book-1/mistakes-part-01.md"};function i(r,e,l,h,p,c){return o(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="第一册-英语初阶-·-全册易错点-·-第1–26课" tabindex="-1">第一册：英语初阶 · 全册易错点 · 第1–26课 <a class="header-anchor" href="#第一册-英语初阶-·-全册易错点-·-第1–26课" aria-label="Permalink to &quot;第一册：英语初阶 · 全册易错点 · 第1–26课&quot;">​</a></h1><p><a href="/life/english/new-concept/book-1/mistakes">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-1/overview">本册介绍</a> · <a href="/life/english/new-concept/book-1/contents">全册课程目录</a> · <a href="/life/english/new-concept/book-1/grammar">全册语法总结</a> · <a href="/life/english/new-concept/book-1/vocabulary">全册单词总结</a> · <a href="/life/english/new-concept/book-1/phrases">全册短语与句型</a> · <a href="/life/english/new-concept/book-1/mistakes">全册易错点</a> · <a href="/life/english/new-concept/book-1/review">综合复习与自测</a></p><h2 id="第一册-英语初阶-·-全册易错点" tabindex="-1">第一册：英语初阶 · 全册易错点 <a class="header-anchor" href="#第一册-英语初阶-·-全册易错点" aria-label="Permalink to &quot;第一册：英语初阶 · 全册易错点 {#第一册-英语初阶-·-全册易错点}&quot;">​</a></h2><p><a href="/life/english/new-concept/book-1/overview">本册介绍</a> · <a href="/life/english/new-concept/book-1/contents">全册课程目录</a> · <a href="/life/english/new-concept/book-1/grammar">全册语法总结</a> · <a href="/life/english/new-concept/book-1/vocabulary">全册单词总结</a> · <a href="/life/english/new-concept/book-1/phrases">全册短语与句型</a> · <a href="/life/english/new-concept/book-1/mistakes">全册易错点</a> · <a href="/life/english/new-concept/book-1/review">综合复习与自测</a></p><h2 id="l1-·-be-动词的一般疑问句" tabindex="-1">L1 · be 动词的一般疑问句 <a class="header-anchor" href="#l1-·-be-动词的一般疑问句" aria-label="Permalink to &quot;L1 · be 动词的一般疑问句 {#l1-·-be-动词的一般疑问句}&quot;">​</a></h2><p>问句中的 this 不在回答中机械重复；用 Yes, it is.，不要写 Yes, this.</p><p><strong>对照例句：</strong> Is this your ticket?</p><p>Is 是前置的系动词，this 是主语，your ticket 是表语；your 限定 ticket 的归属。回答时用 it 代替 this ticket。</p><p><a href="/life/english/new-concept/book-1/unit-01/lesson-001">回看讲解和练习</a></p><h2 id="l2-·-be-动词的一般疑问句" tabindex="-1">L2 · be 动词的一般疑问句 <a class="header-anchor" href="#l2-·-be-动词的一般疑问句" aria-label="Permalink to &quot;L2 · be 动词的一般疑问句 {#l2-·-be-动词的一般疑问句}&quot;">​</a></h2><p>问句中的 this 不在回答中机械重复；用 Yes, it is.，不要写 Yes, this.</p><p><strong>对照例句：</strong> Is this your notebook?</p><p>Is 前置形成问句，this 指近处的一件物品，your notebook 是表语。notebook 为单数，所以使用 is。</p><p><a href="/life/english/new-concept/book-1/unit-01/lesson-002">回看讲解和练习</a></p><h2 id="l3-·-be-动词的否定和缩写" tabindex="-1">L3 · be 动词的否定和缩写 <a class="header-anchor" href="#l3-·-be-动词的否定和缩写" aria-label="Permalink to &quot;L3 · be 动词的否定和缩写 {#l3-·-be-动词的否定和缩写}&quot;">​</a></h2><p>不要用 This not my ...；英语完整陈述句通常仍需 be。</p><p><strong>对照例句：</strong> This is not my umbrella.</p><p>This 是主语，is 是系动词，not 否定整项归属，my umbrella 是表语；my 后保留名词 umbrella。</p><p><a href="/life/english/new-concept/book-1/unit-01/lesson-003">回看讲解和练习</a></p><h2 id="l4-·-be-动词的否定和缩写" tabindex="-1">L4 · be 动词的否定和缩写 <a class="header-anchor" href="#l4-·-be-动词的否定和缩写" aria-label="Permalink to &quot;L4 · be 动词的否定和缩写 {#l4-·-be-动词的否定和缩写}&quot;">​</a></h2><p>不要用 This not my ...；英语完整陈述句通常仍需 be。</p><p><strong>对照例句：</strong> That is not your coat.</p><p>That 指稍远的单数物品；is not 是系表结构的否定，your coat 说明被否定的所属关系。</p><p><a href="/life/english/new-concept/book-1/unit-01/lesson-004">回看讲解和练习</a></p><h2 id="l5-·-身份介绍与特殊疑问句" tabindex="-1">L5 · 身份介绍与特殊疑问句 <a class="header-anchor" href="#l5-·-身份介绍与特殊疑问句" aria-label="Permalink to &quot;L5 · 身份介绍与特殊疑问句 {#l5-·-身份介绍与特殊疑问句}&quot;">​</a></h2><p>He is France 应改为 He is French；国家名可用于 from France。</p><p><strong>对照例句：</strong> This is Eva. She is German.</p><p>第一句用 This is 介绍 Eva；第二句用 She 指代 Eva，German 是国籍形容词，作表语，前面不加 a。</p><p><a href="/life/english/new-concept/book-1/unit-01/lesson-005">回看讲解和练习</a></p><h2 id="l6-·-身份介绍与特殊疑问句" tabindex="-1">L6 · 身份介绍与特殊疑问句 <a class="header-anchor" href="#l6-·-身份介绍与特殊疑问句" aria-label="Permalink to &quot;L6 · 身份介绍与特殊疑问句 {#l6-·-身份介绍与特殊疑问句}&quot;">​</a></h2><p>He is France 应改为 He is French；国家名可用于 from France。</p><p><strong>对照例句：</strong> What make is your camera?</p><p>What make 是询问品牌的疑问词组；is 位于主语 your camera 之前。这里 make 是名词，不是“制作”的动词。</p><p><a href="/life/english/new-concept/book-1/unit-01/lesson-006">回看讲解和练习</a></p><h2 id="l7-·-a-an-与职业名词" tabindex="-1">L7 · a/an 与职业名词 <a class="header-anchor" href="#l7-·-a-an-与职业名词" aria-label="Permalink to &quot;L7 · a/an 与职业名词 {#l7-·-a-an-与职业名词}&quot;">​</a></h2><p>复数职业前不加 a/an；teachers 与 are 配合，不能写 a teachers。</p><p><strong>对照例句：</strong> My sister is an engineer.</p><p>My sister 为第三人称单数主语，后接 is；engineer 的首音是元音音素，因此用 an，而非 a。</p><p><a href="/life/english/new-concept/book-1/unit-01/lesson-007">回看讲解和练习</a></p><h2 id="l8-·-a-an-与职业名词" tabindex="-1">L8 · a/an 与职业名词 <a class="header-anchor" href="#l8-·-a-an-与职业名词" aria-label="Permalink to &quot;L8 · a/an 与职业名词 {#l8-·-a-an-与职业名词}&quot;">​</a></h2><p>复数职业前不加 a/an；teachers 与 are 配合，不能写 a teachers。</p><p><strong>对照例句：</strong> Are your parents teachers?</p><p>Your parents 是复数主语，问句将 are 提前；teachers 为复数职业，不加 a/an。</p><p><a href="/life/english/new-concept/book-1/unit-01/lesson-008">回看讲解和练习</a></p><h2 id="l9-·-be-形容词" tabindex="-1">L9 · be + 形容词 <a class="header-anchor" href="#l9-·-be-形容词" aria-label="Permalink to &quot;L9 · be + 形容词 {#l9-·-be-形容词}&quot;">​</a></h2><p>He friendly 缺少 be；friendly 在这里是形容词，不是动作动词。</p><p><strong>对照例句：</strong> Our new neighbour is very friendly.</p><p>Our new neighbour 是单数主语，is 连接表语 friendly；very 修饰形容词 friendly，说明友好程度。</p><p><a href="/life/english/new-concept/book-1/unit-01/lesson-009">回看讲解和练习</a></p><h2 id="l10-·-be-形容词" tabindex="-1">L10 · be + 形容词 <a class="header-anchor" href="#l10-·-be-形容词" aria-label="Permalink to &quot;L10 · be + 形容词 {#l10-·-be-形容词}&quot;">​</a></h2><p>He friendly 缺少 be；friendly 在这里是形容词，不是动作动词。</p><p><strong>对照例句：</strong> Look at the young artist.</p><p>Look 是祈使句谓语，省略主语 you；at 引出观察对象 the young artist，young 在名词前作定语。</p><p><a href="/life/english/new-concept/book-1/unit-01/lesson-010">回看讲解和练习</a></p><h2 id="l11-·-whose-与物主限定词" tabindex="-1">L11 · whose 与物主限定词 <a class="header-anchor" href="#l11-·-whose-与物主限定词" aria-label="Permalink to &quot;L11 · whose 与物主限定词 {#l11-·-whose-与物主限定词}&quot;">​</a></h2><p>不要将 Whose 写成 Who&#39;s；who is 不表示所有关系。</p><p><strong>对照例句：</strong> Whose scarf is that?</p><p>Whose scarf 是疑问词组，询问归属；is 前置，that 是主语。whose 后接 scarf，不能换成 who&#39;s。</p><p><a href="/life/english/new-concept/book-1/unit-01/lesson-011">回看讲解和练习</a></p><h2 id="l12-·-whose-与物主限定词" tabindex="-1">L12 · whose 与物主限定词 <a class="header-anchor" href="#l12-·-whose-与物主限定词" aria-label="Permalink to &quot;L12 · whose 与物主限定词 {#l12-·-whose-与物主限定词}&quot;">​</a></h2><p>不要将 Whose 写成 Who&#39;s；who is 不表示所有关系。</p><p><strong>对照例句：</strong> This is his bicycle.</p><p>This 是主语，is 是系动词，his bicycle 是表语；his 在 bicycle 前用作物主限定词。</p><p><a href="/life/english/new-concept/book-1/unit-01/lesson-012">回看讲解和练习</a></p><h2 id="l13-·-形容词位置与颜色问句" tabindex="-1">L13 · 形容词位置与颜色问句 <a class="header-anchor" href="#l13-·-形容词位置与颜色问句" aria-label="Permalink to &quot;L13 · 形容词位置与颜色问句 {#l13-·-形容词位置与颜色问句}&quot;">​</a></h2><p>shoes 为复数，问颜色用 are；颜色形容词不变成 greens。</p><p><strong>对照例句：</strong> Her new jacket is green.</p><p>Her new jacket 是主语，new 修饰 jacket；green 位于 is 后作表语，表示颜色，不需要冠词。</p><p><a href="/life/english/new-concept/book-1/unit-01/lesson-013">回看讲解和练习</a></p><h2 id="l14-·-形容词位置与颜色问句" tabindex="-1">L14 · 形容词位置与颜色问句 <a class="header-anchor" href="#l14-·-形容词位置与颜色问句" aria-label="Permalink to &quot;L14 · 形容词位置与颜色问句 {#l14-·-形容词位置与颜色问句}&quot;">​</a></h2><p>shoes 为复数，问颜色用 are；颜色形容词不变成 greens。</p><p><strong>对照例句：</strong> What colour are your shoes?</p><p>What colour 询问颜色，are 与复数主语 your shoes 一致；不因 colour 是单数而改用 is。</p><p><a href="/life/english/new-concept/book-1/unit-01/lesson-014">回看讲解和练习</a></p><h2 id="l15-·-名词复数与复数-be" tabindex="-1">L15 · 名词复数与复数 be <a class="header-anchor" href="#l15-·-名词复数与复数-be" aria-label="Permalink to &quot;L15 · 名词复数与复数 be {#l15-·-名词复数与复数-be}&quot;">​</a></h2><p>these 是复数；不能说 These is your passport。</p><p><strong>对照例句：</strong> These tourists are from Spain.</p><p>These tourists 是复数主语，are from Spain 表来源；these 与复数 tourists 配合，Spain 是国家专名。</p><p><a href="/life/english/new-concept/book-1/unit-01/lesson-015">回看讲解和练习</a></p><h2 id="l16-·-名词复数与复数-be" tabindex="-1">L16 · 名词复数与复数 be <a class="header-anchor" href="#l16-·-名词复数与复数-be" aria-label="Permalink to &quot;L16 · 名词复数与复数 be {#l16-·-名词复数与复数-be}&quot;">​</a></h2><p>these 是复数；不能说 These is your passport。</p><p><strong>对照例句：</strong> Are these your passports?</p><p>Are 前置，these 是复数主语，your passports 是复数名词表语；your 的形式不因多人多本护照而改变。</p><p><a href="/life/english/new-concept/book-1/unit-01/lesson-016">回看讲解和练习</a></p><h2 id="l17-·-复数职业与-their" tabindex="-1">L17 · 复数职业与 their <a class="header-anchor" href="#l17-·-复数职业与-their" aria-label="Permalink to &quot;L17 · 复数职业与 their {#l17-·-复数职业与-their}&quot;">​</a></h2><p>their 不等于 they are；后者缩写为 they&#39;re。多人可以共用一个 office，不能只看 their 就加复数。</p><p><strong>对照例句：</strong> Maya and Leo are office assistants.</p><p>Maya and Leo 是 and 连接的复数主语，are 后接复数职业 office assistants。office 作为名词修饰语保持单数。</p><p><a href="/life/english/new-concept/book-1/unit-01/lesson-017">回看讲解和练习</a></p><h2 id="l18-·-复数职业与-their" tabindex="-1">L18 · 复数职业与 their <a class="header-anchor" href="#l18-·-复数职业与-their" aria-label="Permalink to &quot;L18 · 复数职业与 their {#l18-·-复数职业与-their}&quot;">​</a></h2><p>their 不等于 they are；后者缩写为 they&#39;re。多人可以共用一个 office，不能只看 their 就加复数。</p><p><strong>对照例句：</strong> Their office is on the first floor.</p><p>Their office 虽由多人拥有，但 office 仍是一个，因此用 is；on the first floor 是地点表语。</p><p><a href="/life/english/new-concept/book-1/unit-01/lesson-018">回看讲解和练习</a></p><h2 id="l19-·-主格和宾格" tabindex="-1">L19 · 主格和宾格 <a class="header-anchor" href="#l19-·-主格和宾格" aria-label="Permalink to &quot;L19 · 主格和宾格 {#l19-·-主格和宾格}&quot;">​</a></h2><p>look at they 应改为 look at them；they 在此不是主语。</p><p><strong>对照例句：</strong> The runners are tired and hungry.</p><p>The runners 是复数主语，are 后接两个由 and 连接的表语 tired 和 hungry；形容词不加复数 s。</p><p><a href="/life/english/new-concept/book-1/unit-01/lesson-019">回看讲解和练习</a></p><h2 id="l20-·-主格和宾格" tabindex="-1">L20 · 主格和宾格 <a class="header-anchor" href="#l20-·-主格和宾格" aria-label="Permalink to &quot;L20 · 主格和宾格 {#l20-·-主格和宾格}&quot;">​</a></h2><p>look at they 应改为 look at them；they 在此不是主语。</p><p><strong>对照例句：</strong> Look at them near the gate.</p><p>Look at 是观察动作，them 是介词 at 的宾语；near the gate 补充被观察者所在的位置。</p><p><a href="/life/english/new-concept/book-1/unit-01/lesson-020">回看讲解和练习</a></p><h2 id="l21-·-which-与-one-的替代" tabindex="-1">L21 · which 与 one 的替代 <a class="header-anchor" href="#l21-·-which-与-one-的替代" aria-label="Permalink to &quot;L21 · which 与 one 的替代 {#l21-·-which-与-one-的替代}&quot;">​</a></h2><p>one 替代可数名词单数，不能用来替代不可数的 water。</p><p><strong>对照例句：</strong> Please give me the empty box.</p><p>Please 表礼貌；give 是祈使句谓语，me 为间接宾语，the empty box 为直接宾语；empty 修饰 box。</p><p><a href="/life/english/new-concept/book-1/unit-01/lesson-021">回看讲解和练习</a></p><h2 id="l22-·-which-与-one-的替代" tabindex="-1">L22 · which 与 one 的替代 <a class="header-anchor" href="#l22-·-which-与-one-的替代" aria-label="Permalink to &quot;L22 · which 与 one 的替代 {#l22-·-which-与-one-的替代}&quot;">​</a></h2><p>one 替代可数名词单数，不能用来替代不可数的 water。</p><p><strong>对照例句：</strong> Which notebook do you want: the red one or the blue one?</p><p>Which notebook 是 want 的疑问宾语；do 帮助构成问句。两个 one 都替代 notebook，red 与 blue 提供选择依据。</p><p><a href="/life/english/new-concept/book-1/unit-01/lesson-022">回看讲解和练习</a></p><h2 id="l23-·-ones-与复数选择" tabindex="-1">L23 · ones 与复数选择 <a class="header-anchor" href="#l23-·-ones-与复数选择" aria-label="Permalink to &quot;L23 · ones 与复数选择 {#l23-·-ones-与复数选择}&quot;">​</a></h2><p>不能把复数 plates 替换为 one；some 后单数 plate 通常不表示“一些盘子”。</p><p><strong>对照例句：</strong> Please give us the clean plates.</p><p>Give 后先接表示接受者的宾格 us，再接 the clean plates；plates 是复数，clean 仍不变化。</p><p><a href="/life/english/new-concept/book-1/unit-01/lesson-023">回看讲解和练习</a></p><h2 id="l24-·-ones-与复数选择" tabindex="-1">L24 · ones 与复数选择 <a class="header-anchor" href="#l24-·-ones-与复数选择" aria-label="Permalink to &quot;L24 · ones 与复数选择 {#l24-·-ones-与复数选择}&quot;">​</a></h2><p>不能把复数 plates 替换为 one；some 后单数 plate 通常不表示“一些盘子”。</p><p><strong>对照例句：</strong> I want the small ones beside the sink.</p><p>I 是主语，want 是谓语，the small ones 是宾语；ones 指已知的复数物品，beside the sink 补充位置。</p><p><a href="/life/english/new-concept/book-1/unit-01/lesson-024">回看讲解和练习</a></p><h2 id="l25-·-there-is-与位置介词" tabindex="-1">L25 · there is 与位置介词 <a class="header-anchor" href="#l25-·-there-is-与位置介词" aria-label="Permalink to &quot;L25 · there is 与位置介词 {#l25-·-there-is-与位置介词}&quot;">​</a></h2><p>There is the kettle 常不适合首次引入物品；首次介绍通常用 a kettle。</p><p><strong>对照例句：</strong> There is a clock above the fridge.</p><p>There is 引出新信息 a clock；above the fridge 说明时钟高于冰箱，不保证与冰箱表面接触。</p><p><a href="/life/english/new-concept/book-1/unit-02/lesson-025">回看讲解和练习</a></p><h2 id="l26-·-there-is-与位置介词" tabindex="-1">L26 · there is 与位置介词 <a class="header-anchor" href="#l26-·-there-is-与位置介词" aria-label="Permalink to &quot;L26 · there is 与位置介词 {#l26-·-there-is-与位置介词}&quot;">​</a></h2><p>There is the kettle 常不适合首次引入物品；首次介绍通常用 a kettle。</p><p><strong>对照例句：</strong> The kettle is on the shelf.</p><p>The kettle 是已知物品，is 后用 on the shelf 说明它的位置；不是首次介绍“这里有什么”的存在句。</p><p><a href="/life/english/new-concept/book-1/unit-02/lesson-026">回看讲解和练习</a></p>',135)])])}const g=a(s,[["render",i]]);export{f as __pageData,g as default};
